from donnees import C,E

CHAPITRES=[]
CHAPITRES.append(C(9,'Décrire et mesurer un mouvement','Un passager assis est-il immobile ?',
['Choisir un objet et un référentiel.','Décrire trajectoire, direction, sens et évolution de la vitesse.','Calculer distance, durée et vitesse avec des unités cohérentes.'],['Durées, distances et proportionnalité.'],[
('Le mouvement dépend du référentiel',r'Pour décrire un mouvement, on choisit l’objet étudié et un référentiel, c’est-à-dire un objet de référence auquel on associe des repères d’espace et de temps. Un passager assis est immobile par rapport à son siège, mais en mouvement par rapport au quai lorsque le train roule. Ces descriptions sont compatibles parce qu’elles utilisent des références différentes.','c09-chrono','Des positions relevées à intervalles de temps égaux : l’écartement renseigne sur l’évolution de la valeur de la vitesse.'),
('Décrire la trajectoire et la vitesse',r'La trajectoire est l’ensemble des positions successives du point étudié dans le référentiel choisi. Elle est rectiligne, circulaire ou plus généralement curviligne. La vitesse possède une direction, un sens et une valeur. Un mouvement circulaire à valeur de vitesse constante change néanmoins de direction. « Uniforme » signifie que la valeur de la vitesse reste constante ; cela ne signifie pas forcément rectiligne.','',''),
('Relier distance, durée et vitesse',r'La vitesse moyenne sur un trajet est $v_{\mathrm{moy}}=d/\Delta t$. Pour un mouvement uniforme, on utilise $d=v\Delta t$ et $\Delta t=d/v$. Si $d$ est en m et $\Delta t$ en s, $v$ est en m/s. Pour passer de m/s à km/h, multiplier par $3{,}6$ ; pour le passage inverse, diviser par $3{,}6$. Une vitesse moyenne ne décrit pas tous les instants du trajet.','c09-graphique','Sur ce graphique de position rectiligne, une pente plus forte correspond à une valeur de vitesse plus élevée.'),
('Mesurer sans inventer une précision',r'Une chronophotographie ou une vidéo fournit des positions et des instants. Pour exploiter l’image, il faut une échelle de distance, une durée entre images et un point suivi cohérent. La perspective peut déformer les longueurs. Une mesure avec un chronomètre manuel comporte une variabilité due au déclenchement. Répéter et comparer aide à estimer la qualité du résultat.','','')],
r'Une cycliste parcourt $180\unite m$ en $30\unite s$. Sa vitesse moyenne vaut $180/30=6{,}0\unite{m/s}$, soit $6{,}0\times3{,}6=21{,}6\unite{km/h}$. Si elle conserve cette vitesse pendant $50\unite s$, elle parcourt $d=6{,}0\times50=300\unite m$. La dernière conclusion suppose bien un mouvement uniforme sur la durée annoncée.',
r'\textbf{Question.} Un petit chariot avance-t-il uniformément ? Filmer un déplacement rectiligne sur une table, avec un repère de longueur dans le plan du mouvement. Choisir le centre d’une même roue ou un point repéré du chariot. Relever les positions toutes les mêmes durées, puis tracer position en fonction du temps. Comparer les distances successives et discuter les erreurs de lecture. \textbf{À rendre :} référentiel, tableau, graphique et conclusion. Aucune mesure ne se fait sur une route ouverte.',
['Un mouvement est décrit dans un référentiel annoncé.','Trajectoire et évolution de la vitesse sont deux descriptions complémentaires.','À temps égaux, des déplacements égaux indiquent une valeur de vitesse constante.','La vitesse moyenne vaut distance totale divisée par durée totale.','Les unités doivent être converties avant le calcul.'],
r'Faire la moyenne de deux vitesses ne donne pas toujours la vitesse moyenne du trajet : il faut utiliser la distance totale et la durée totale.',[
E('Le référentiel','Un livre posé dans un train est-il immobile par rapport au train ?@@Peut-il être en mouvement par rapport au sol ?','Oui, s’il reste posé à la même place.@@Oui lorsque le train roule ; la réponse dépend du référentiel.'),
E('La trajectoire','Un point décrit un cercle autour d’un axe. Comment qualifier la trajectoire ?@@Un mouvement en ligne droite est-il circulaire ?','Circulaire.@@Non : sa trajectoire est rectiligne dans le référentiel considéré.'),
E('Temps égaux','Sur une chronophotographie, les écarts augmentent pour des durées égales. Que peut-on dire de la valeur de la vitesse ?@@Quelle donnée faut-il vérifier ?','Elle augmente : le mouvement est accéléré au sens de sa valeur de vitesse.@@Les intervalles de temps doivent être réellement égaux et les longueurs comparables sur l’image.'),
E('Une vitesse directe',r'Un mobile parcourt $40\unite m$ en $8\unite s$. Calculer sa vitesse moyenne.@@Donner l’unité.',r'$v=40/8=5\unite{m/s}$.@@Mètre par seconde, car les données sont en mètres et secondes.',calculs=[('40/8',5)]),
E('Convertir',r'Convertir $10\unite{m/s}$ en km/h.@@Convertir $72\unite{km/h}$ en m/s.',r'$10\times3{,}6=36\unite{km/h}$.@@$72/3{,}6=20\unite{m/s}$.',calculs=[('10*3.6',36),('72/3.6',20)]),
E('Calculer une distance',r'Un chariot roule à $0{,}40\unite{m/s}$ pendant $15\unite s$ à vitesse constante. Quelle distance parcourt-il ?@@Et pendant une durée double ?',r'$d=0{,}40\times15=6{,}0\unite m$.@@$12\unite m$ si la vitesse reste la même.',calculs=[('.4*15',6),('.4*30',12)]),
E('Calculer une durée',r'Une marcheuse parcourt $1{,}8\unite{km}$ à $6\unite{km/h}$ de moyenne. Calculer la durée en heures.@@Convertir en minutes.',r'$\Delta t=1{,}8/6=0{,}30\unite h$.@@$0{,}30\times60=18\unite{min}$.',calculs=[('1.8/6',.3),('.3*60',18)]),
E('Lire des positions',r'Aux instants 0, 2, 4 et 6 s, les positions sont 0, 3, 6 et 9 m. Décrire le mouvement rectiligne.@@Calculer la vitesse.',r'Les écarts sont toujours de $3\unite m$ en $2\unite s$ : la valeur de la vitesse est constante.@@$v=3/2=1{,}5\unite{m/s}$.',calculs=[('3/2',1.5)]),
E('Uniforme sur un cercle','Un siège de manège décrit un cercle à valeur de vitesse constante. Sa direction de vitesse reste-t-elle fixe ?@@Comment qualifier le mouvement ?','Non : la direction est tangente au cercle et varie avec la position.@@C’est un mouvement circulaire uniforme ; le vecteur vitesse n’est pas constant.'),
E('Une vidéo étalonnée',r'Une règle de $1\unite m$ occupe $200$ pixels ; un déplacement occupe $80$ pixels. Quelle distance réelle ?@@Ce déplacement dure $0{,}20\unite s$. Calculer la vitesse moyenne.',r'$80/200=0{,}40\unite m$, si règle et mouvement sont dans le même plan.@@$0{,}40/0{,}20=2{,}0\unite{m/s}$.',calculs=[('80/200',.4),('.4/.2',2)]),
E('Deux parties d’un trajet',r'Un trajet de $60\unite{km}$ dure $1\unite h$ ; le retour de $60\unite{km}$ dure $2\unite h$. Calculer la vitesse moyenne de l’aller-retour.@@Pourquoi $45\unite{km/h}$ serait-il faux ?',r'$d_{\rm total}=120\unite{km}$ et $\Delta t=3\unite h$ ; $v=40\unite{km/h}$.@@$45$ est la moyenne arithmétique de 60 et 30, mais les durées ne sont pas égales.',calculs=[('120/3',40)]),
E('Un arrêt compte-t-il ?',r'Un bus parcourt $12\unite{km}$ en $20\unite{min}$, puis s’arrête $10\unite{min}$. Calculer sa moyenne sur les 30 minutes.@@La vitesse pendant l’arrêt vaut-elle cette moyenne ?',r'$30\unite{min}=0{,}5\unite h$ ; $v=12/0{,}5=24\unite{km/h}$.@@Non : pendant l’arrêt, la vitesse par rapport au sol est nulle.',calculs=[('12/.5',24)]),
E('Une conclusion trop forte','Une voiture parcourt 100 m en 5 s. Peut-on prouver qu’elle était à 20 m/s à chaque instant ?@@Que permet réellement le calcul ?','Non : elle peut avoir accéléré puis ralenti.@@Il donne une vitesse moyenne de 20 m/s sur ce tronçon, pas toute son évolution temporelle.'),
E('Un graphique ambigu','Une courbe représente une position qui diminue linéairement au cours du temps. Le mobile ralentit-il forcément ?@@Quelle distinction faut-il faire ?','Non : une position décroissante peut correspondre à un mouvement uniforme dans le sens opposé à l’axe choisi.@@Il faut distinguer signe de l’évolution de position et valeur positive de la vitesse.'),
E('Comparer des mesures',r'Trois temps pour $10\unite m$ valent $4{,}8$, $5{,}0$ et $5{,}2\unite s$. Calculer le temps moyen.@@Donner une vitesse représentative et discuter sa précision.',r'$\bar t=(4{,}8+5{,}0+5{,}2)/3=5{,}0\unite s$.@@$v\approx10/5{,}0=2{,}0\unite{m/s}$. La dispersion et le déclenchement manuel ne justifient pas de nombreuses décimales.',calculs=[('(4.8+5+5.2)/3',5)])],
E('Choisir le meilleur trajet',r'A mesure $1{,}2\unite{km}$ à $4\unite{km/h}$ de moyenne. B mesure $1{,}5\unite{km}$ à $6\unite{km/h}$, avec $3\unite{min}$ d’arrêt supplémentaire. Calculer les durées totales.@@Quel trajet est le plus rapide ?@@Quelle hypothèse pourrait changer la conclusion ?',r'A : $1{,}2/4=0{,}30\unite h=18\unite{min}$. B : $1{,}5/6=0{,}25\unite h=15\unite{min}$, puis 3 minutes : 18 minutes.@@Les durées sont égales dans ce modèle.@@Les vitesses moyennes, la durée d’arrêt ou les distances peuvent varier. La conclusion est conditionnelle aux données.',calculs=[('1.2/4*60',18),('1.5/6*60+3',18)])))

CHAPITRES.append(C(10,'Interactions et forces','Pourquoi un objet posé ne tombe-t-il pas ?',
['Identifier les objets en interaction avec un système.','Distinguer contact et action à distance.','Représenter une force par quatre caractéristiques.'],['Décrire le mouvement et choisir un système.'],[
('Délimiter le système',r'Le système est l’objet ou l’ensemble d’objets que l’on choisit d’étudier. On recherche les objets extérieurs qui agissent sur lui. Un livre posé sur une table interagit notamment avec la Terre et la table. L’interaction avec la Terre est à distance ; celle avec la table est de contact. On indique si l’action de l’air est négligée dans le modèle.','c10-doi','Diagramme objet-interactions du livre : trait plein pour un contact, pointillé pour une interaction à distance.'),
('Modéliser une action',r'Une force représente l’action d’un objet sur un autre. Elle possède un point d’application, une direction, un sens et une valeur en newtons (N). La direction est la droite support ; le sens précise vers quel côté l’action s’exerce. Une flèche représente ces caractéristiques : origine, orientation, pointe et longueur donnée par une échelle. Le nom de l’auteur de l’action doit être identifiable.','',''),
('Mesurer et dessiner',r'Le dynamomètre mesure une valeur de force. Vérifier son zéro, son calibre et son alignement avec l’action. Pour dessiner une force de $4\unite N$ à l’échelle $1\unite{cm}$ pour $2\unite N$, tracer une flèche de $2\unite{cm}$. Une flèche longue ne donne pas une valeur si aucune échelle n’est annoncée.','c10-forces','Pour le livre immobile, deux actions verticales opposées peuvent se compenser dans le modèle où les autres actions sont négligées.'),
('Ce que produit une action',r'Une action peut déformer un objet ou modifier son mouvement : valeur de vitesse, direction ou sens. Un objet immobile peut subir plusieurs forces qui se compensent. Une force n’est donc pas nécessairement synonyme de mouvement visible. Les deux actions d’une interaction s’exercent sur deux objets différents : on ne les additionne pas comme des forces appliquées au même système.','','')],
r'Un ballon est suspendu par un fil et immobile. Sur le ballon, on représente l’action de la Terre vers le bas et celle du fil vers le haut. Si leurs valeurs sont toutes deux $2\unite N$, à l’échelle $1\unite{cm}$ pour $1\unite N$, chaque flèche mesure $2\unite{cm}$. Ces forces sont appliquées au même ballon et se compensent dans le modèle.',
r'\textbf{Question.} Quelles actions s’exercent sur un objet suspendu ? Suspendre une masse scolaire à un dynamomètre adapté, sans dépasser le calibre. Relever la valeur lorsque l’objet est immobile. Construire le diagramme objet-interactions, puis représenter les forces avec une échelle choisie. Incliner légèrement le support uniquement selon les consignes : comparer la direction de l’instrument à celle de l’action mesurée. \textbf{À rendre :} système, interactions, mesure, flèches légendées et hypothèses.',
['Le bilan des actions dépend du système choisi.','Un contact et une interaction à distance sont deux catégories différentes.','Une force se représente par un point, une direction, un sens et une valeur.','Le newton est une unité de force ; le kilogramme est une unité de masse.','Un objet immobile peut subir plusieurs forces non nulles.'],
r'La direction « verticale » et le sens « vers le bas » sont deux informations distinctes ; l’une ne remplace pas l’autre.',[
E('Choisir le système','On étudie un ballon tenu par une main. Quel est le système ?@@La main est-elle alors extérieure au système ?','Le ballon, si c’est l’objet annoncé.@@Oui ; son action sur le ballon doit être examinée.'),
E('Contact ou distance','Classer l’action d’une table sur un livre et celle de la Terre sur ce livre.@@Un aimant doit-il toujours toucher un trombone pour agir ?','Table : contact ; Terre : distance.@@Non : l’interaction magnétique peut s’exercer à distance.'),
E('Quatre caractéristiques','Nommer les quatre caractéristiques d’une force.@@Donner son unité.','Point d’application, direction, sens et valeur.@@Le newton, symbole N.'),
E('L’appareil adapté','Quel appareil mesure la valeur d’une force ?@@Pourquoi vérifier le calibre ?','Un dynamomètre.@@Pour éviter de le détériorer et utiliser une plage de mesure adaptée à la valeur attendue.'),
E('Deux sens','Deux forces sont verticales, l’une vers le haut et l’autre vers le bas. Ont-elles la même direction ?@@Ont-elles le même sens ?','Oui : leurs droites supports sont verticales.@@Non : les sens sont opposés.'),
E('Dessiner à l’échelle',r'À $1\unite{cm}$ pour $2\unite N$, quelle longueur pour $6\unite N$ ?@@Pour $1\unite N$ ?',r'$6/2=3\unite{cm}$.@@$1/2=0{,}5\unite{cm}$.',calculs=[('6/2',3),('1/2',.5)]),
E('Lire une longueur',r'Une flèche mesure $4\unite{cm}$ à l’échelle $1\unite{cm}$ pour $0{,}5\unite N$. Quelle force représente-t-elle ?@@Changer l’échelle change-t-il l’action réelle ?',r'$4\times0{,}5=2\unite N$.@@Non : cela change seulement la longueur choisie pour la représentation.',calculs=[('4*.5',2)]),
E('Un objet immobile','Un objet immobile subit-il forcément une force nulle de la Terre ?@@Comment peut-il rester immobile ?','Non : il peut subir son poids.@@D’autres forces, par exemple celle d’un support, peuvent compenser cette action dans le modèle étudié.'),
E('Le livre sur la table','Construire verbalement le diagramme des interactions du livre, en négligeant l’air.@@Quelles forces représenter sur le livre ?','Le livre est relié à la Terre par une interaction à distance et à la table par une interaction de contact.@@L’action de la Terre vers le bas et celle de la table vers le haut, dans cette situation simple.'),
E('Une balle qui tourne','Une balle peut-elle subir une action qui change sa direction sans augmenter la valeur de sa vitesse ?@@Donner un exemple de mouvement compatible.','Oui : la vitesse peut changer de direction à valeur constante.@@Un mouvement circulaire uniforme, par exemple une balle retenue dans un mouvement circulaire adapté ; il ne faut pas réaliser de lancer dangereux.'),
E('Deux objets, deux actions','Une main pousse une boîte. La boîte agit-elle aussi sur la main ?@@Ces deux actions se compensent-elles dans le bilan de la boîte ?','Oui : il s’agit d’une interaction réciproque.@@Non : une force s’applique à la boîte, l’autre à la main. Le bilan de la boîte n’inclut que les forces qui s’appliquent à la boîte.'),
E('Un bilan incomplet','Pour un objet suspendu immobile, un élève ne dessine que la force du fil. Quelle action manque ?@@Quelle erreur de conclusion pourrait-il faire ?','L’action de la Terre, le poids.@@Il pourrait croire qu’une seule force vers le haut suffit à expliquer l’immobilité, alors que les actions doivent être comparées.'),
E('Une lecture discutable','Un dynamomètre affiche 0,2 N avant tout accrochage puis 2,2 N avec l’objet. Si le décalage reste constant, quelle correction proposer ?@@Quelle précaution est préférable ?','Soustraire le décalage : 2,0 N.@@Régler le zéro correctement avant la mesure et vérifier la stabilité, plutôt que corriger sans contrôle.',calculs=[('2.2-.2',2)]),
E('Une flèche sans légende','Deux élèves tracent des flèches de longueurs différentes pour la même force. Lequel a tort ?@@Quelles informations vérifier avant de décider ?','Aucun nécessairement : leurs échelles peuvent être différentes.@@Comparer échelle, valeur, point d’application, direction, sens et système étudié.'),
E('Changer le système','On étudie d’abord un objet suspendu, puis l’ensemble objet-fil. L’action du fil sur l’objet a-t-elle encore le même statut ?@@Quelle action extérieure faut-il alors chercher ?','Elle devient une interaction interne à l’ensemble objet-fil.@@Il faut notamment considérer l’action du support sur le fil et celle de la Terre sur l’ensemble.')],
E('Une suspension à expliquer',r'Un objet est immobile sous un fil vertical. Le dynamomètre indique $3\unite N$. Définir le système et deux interactions.@@Tracer verbalement les forces à l’échelle $1\unite{cm}$ pour $1{,}5\unite N$.@@Un élève dit « aucune force puisque rien ne bouge ». Répondre.',r'Le système est l’objet ; il interagit avec le fil par contact et avec la Terre à distance.@@Deux flèches verticales opposées de $3/1{,}5=2\unite{cm}$, si le modèle à deux forces est valable.@@L’immobilité n’implique pas l’absence de forces. Ici, leurs effets se compensent ; leurs valeurs ne sont pas nulles.',calculs=[('3/1.5',2)])))

CHAPITRES.append(C(11,'Poids, masse et gravitation','Pourquoi pèse-t-on moins sur la Lune ?',
['Distinguer masse et poids, instruments et unités.','Utiliser une proportionnalité entre poids et masse.','Décrire qualitativement la gravitation et ses limites de modèle.'],['Force, masse et proportionnalité.'],[
('Une distinction indispensable',r'La masse $m$, mesurée avec une balance et exprimée en kilogrammes, ne dépend pas du lieu dans les situations du collège. Le poids $P$ est la force de pesanteur exercée sur l’objet ; il se mesure avec un dynamomètre et s’exprime en newtons. Près de la surface terrestre, il est vertical et dirigé vers le centre de la Terre dans le modèle sphérique.','c11-terrelune','Même objet : masse identique, poids différent selon l’astre. Les flèches représentent les poids, pas les masses.'),
('Une relation de proportionnalité',r'En un lieu donné, le poids est proportionnel à la masse : $P=mg$. Le coefficient $g$ s’exprime en N/kg. On prend souvent $g\approx10\unite{N/kg}$ sur Terre pour les calculs simples, ou $9{,}8\unite{N/kg}$ si l’énoncé le précise ; sur la Lune, environ $1{,}6\unite{N/kg}$. Convertir la masse en kilogrammes avant de calculer. Ces valeurs sont des approximations locales.','',''),
('Mesurer et exploiter un graphique',r'Suspendre plusieurs masses connues permet de tracer $P$ en fonction de $m$. Une droite passant près de l’origine traduit la proportionnalité ; le quotient $P/m$ donne une estimation de $g$. Un écart de mesure se discute avant de déclarer la loi fausse. La droite doit être construite à partir des mesures, sans relier mécaniquement tous les points par une ligne brisée.','c11-graphique','Données idéales pour comparer les pentes sur Terre et sur la Lune ; une vraie mesure présenterait une dispersion.'),
('La gravitation et la suite du cycle',r'La gravitation est une interaction attractive à distance entre objets possédant une masse. Elle intervient dans les mouvements des planètes et des satellites. Plus les masses sont grandes, plus l’action est forte ; l’éloignement la diminue. Dans ce manuel, on travaille surtout qualitativement. L’exploitation numérique de la loi de gravitation fournie et la structure de l’atome seront approfondies en 3e. L’impesanteur apparente d’astronautes en orbite ne signifie pas que la Terre n’agit plus sur eux.','','')],
r'Un sac a une masse de $600\unite g=0{,}600\unite{kg}$. Avec $g=10\unite{N/kg}$, son poids terrestre est $P=0{,}600\times10=6{,}0\unite N$. Sur la Lune, $P=0{,}600\times1{,}6=0{,}96\unite N$. Le sac ne perd pas de matière pendant ce changement de lieu : sa masse reste $0{,}600\unite{kg}$.',
r'\textbf{Question.} Poids et masse sont-ils proportionnels ? Utiliser des masses scolaires, une balance et un dynamomètre adapté. Relever au moins quatre couples $(m;P)$, en notant m en kg et P en N. Tracer le graphique et estimer $P/m$ pour chaque couple. Repérer un décalage du zéro éventuel. \textbf{À rendre :} tableau, droite d’ajustement visuelle, estimation de $g$ et limites. Le déplacement vers la Lune est étudié par données documentaires, pas par une manipulation.',
['La masse s’exprime en kg et le poids en N.','Le poids est une force, avec direction et sens.','À lieu donné, $P=mg$.','Le coefficient $g$ dépend du lieu.','La gravitation agit à distance et reste présente en orbite.'],
r'Ne pas utiliser $m=600$ dans $P=mg$ si la masse est donnée en grammes et $g$ en N/kg : il faut d’abord écrire $m=0{,}600\unite{kg}$.',[
E('Associer les unités','Associer kilogramme et newton à masse et poids.@@Quel instrument mesure le poids ?','Kilogramme pour la masse ; newton pour le poids.@@Le dynamomètre.'),
E('Le lieu change','La masse d’un objet change-t-elle lors d’un voyage Terre-Lune dans le modèle du cours ?@@Et son poids ?','Non, s’il ne gagne ni ne perd de matière.@@Oui, car le coefficient de pesanteur local change.'),
E('Convertir une masse',r'Convertir $250\unite g$ en kg.@@Convertir $1{,}5\unite{kg}$ en g.',r'$0{,}250\unite{kg}$.@@$1\,500\unite g$.',calculs=[('250/1000',.25),('1.5*1000',1500)]),
E('Un poids simple',r'Calculer le poids de $2\unite{kg}$ avec $g=10\unite{N/kg}$.@@Donner sa direction et son sens près du sol.',r'$P=2\times10=20\unite N$.@@Direction verticale ; sens vers le bas, vers le centre de la Terre dans le modèle.',calculs=[('2*10',20)]),
E('Une interaction','La gravitation est-elle une action de contact ?@@Est-elle attractive dans les situations étudiées ?','Non : elle s’exerce à distance.@@Oui : les objets massifs s’attirent.'),
E('Un petit objet',r'Calculer le poids terrestre d’un objet de $80\unite g$ avec $g=10\unite{N/kg}$.@@Quelle erreur ferait-on en oubliant la conversion ?',r'$80\unite g=0{,}080\unite{kg}$ ; $P=0{,}80\unite N$.@@On trouverait à tort $800\unite N$, soit mille fois trop.',calculs=[('80/1000*10',.8)]),
E('Retrouver la masse',r'Un objet a un poids de $35\unite N$ avec $g=10\unite{N/kg}$. Quelle masse ?@@Exprimer en grammes.',r'$m=P/g=35/10=3{,}5\unite{kg}$.@@$3\,500\unite g$.',calculs=[('35/10',3.5)]),
E('Estimer le coefficient',r'Une masse de $0{,}50\unite{kg}$ pèse $4{,}9\unite N$. Estimer $g$.@@Quelle unité utiliser ?',r'$g=P/m=4{,}9/0{,}50=9{,}8\unite{N/kg}$.@@Newton par kilogramme.',calculs=[('4.9/.5',9.8)]),
E('Terre et Lune',r'Une masse de $5\unite{kg}$ est étudiée avec $g_T=10$ et $g_L=1{,}6\unite{N/kg}$. Calculer les poids.@@Quel rapport entre les poids ?',r'$P_T=50\unite N$ ; $P_L=8\unite N$.@@$50/8=6{,}25$ ; le poids terrestre est environ six fois plus grand avec ces valeurs arrondies.',calculs=[('5*1.6',8),('50/8',6.25)]),
E('Une droite',r'Les couples $(m;P)$ sont $(0{,}1;1)$, $(0{,}2;2)$ et $(0{,}3;3)$, en kg et N. Quel modèle ?@@Prévoir le poids de $0{,}45\unite{kg}$.',r'Une proportionnalité de coefficient $10\unite{N/kg}$.@@$P=0{,}45\times10=4{,}5\unite N$.',calculs=[('.45*10',4.5)]),
E('Une balance détournée','Un pèse-personne terrestre transforme une force mesurée en une indication en kg. Pourquoi cette indication peut-elle être fausse sur la Lune ?@@Quel appareil comparerait des masses sans cette conversion locale ?','Son réglage suppose la pesanteur terrestre ; une même masse exerce une force plus faible sur la Lune.@@Une balance comparant l’objet à des masses étalons dans les mêmes conditions, si son fonctionnement est adapté.'),
E('La phrase du quotidien',r'Une personne dit « je pèse 50 kg ». Reformuler scientifiquement.@@Quel serait son poids avec $g=10\unite{N/kg}$ ?',r'Sa masse est de $50\unite{kg}$.@@Son poids vaut $P=50\times10=500\unite N$ dans ces conditions.',calculs=[('50*10',500)]),
E('Un zéro décalé','Un graphique expérimental de P en fonction de m coupe l’axe vertical à 0,3 N. Quelle cause possible ?@@Doit-on modifier la loi immédiatement ?','Un dynamomètre mal réglé au zéro peut produire ce décalage.@@Non : on contrôle d’abord le zéro, le protocole, les unités et les autres sources d’erreur.'),
E('Une orbite','Des astronautes flottent dans une station en orbite. Peut-on conclure que la gravitation a disparu ?@@Quelle idée qualitative explique leur situation ?','Non : l’attraction terrestre contribue au mouvement orbital.@@La station et les objets qu’elle contient sont en chute commune autour de la Terre ; l’impesanteur apparente ne signifie pas absence d’interaction.'),
E('Une donnée de gravitation','Un modèle documentaire indique que doubler une distance entre deux objets divise la force gravitationnelle par quatre. Si elle valait 12 N, quelle nouvelle valeur ?@@Cette règle donne-t-elle à elle seule le poids de tout objet ?',r'$12/4=3\unite N$.@@Non : il faut connaître le système, les masses, les distances et le domaine du modèle. Ici on exploite seulement une règle fournie pour préparer la suite.',calculs=[('12/4',3)])],
E('Le colis lunaire',r'Un colis a une masse de $750\unite g$. Calculer son poids terrestre avec $g_T=9{,}8\unite{N/kg}$ et lunaire avec $g_L=1{,}6\unite{N/kg}$.@@Choisir un calibre parmi 1 N, 5 N et 10 N pour la mesure terrestre.@@Si le dynamomètre affiche 0 N en chute libre, que peut-on conclure sur la masse ?',r'$m=0{,}750\unite{kg}$ ; $P_T=7{,}35\unite N$ et $P_L=1{,}20\unite N$.@@Le calibre 10 N convient ; 1 N et 5 N seraient dépassés.@@On ne conclut pas à une masse nulle. L’instrument en chute ne fonctionne plus comme une suspension statique ; la masse reste $0{,}750\unite{kg}$.',calculs=[('.75*9.8',7.35),('.75*1.6',1.2)])))
